mapper.select:
/* BatchExecutionMapper.selectBatchExecutionList 검색 조건에 맞는 실행 이력 목록을 페이징 조회한다. */
SELECT

FROM TB_DSPT_EXEC_L E
JOIN TB_DSPT_JOB_M J ON J.JOB_ID = E.JOB_ID

ORDER BY E.DSPT_EXEC_SN DESC
LIMIT #{size} OFFSET #{offset}

/* BatchExecutionMapper.selectBatchExecution 배치실행일련번호로 실행 이력 1건을 조회한다. */
SELECT

FROM TB_DSPT_EXEC_L E
JOIN TB_DSPT_JOB_M J ON J.JOB_ID = E.JOB_ID
WHERE E.DSPT_EXEC_SN = #{dsptExecSn}

/* BatchExecutionMapper.selectFiredTriggerCount 클러스터 전체에서 해당 Quartz Job이 실행 중인지(QRTZ_FIRED_TRIGGERS) 확인한다. */
SELECT COUNT(*)
FROM QRTZ_FIRED_TRIGGERS
WHERE SCHED_NAME = #{schedNm}
  AND JOB_NAME   = #{jobId}
  AND JOB_GROUP  = #{wrkMdulCd}
  AND STATE      = 'EXECUTING'

mapper.insert:
/* BatchExecutionMapper.insertBatchExecution 실행 이력을 등록한다. */
SELECT NEXTVAL('SQ_TB_DSPT_EXEC_L_DSPT_EXEC_SN')
INSERT INTO TB_DSPT_EXEC_L ( DSPT_EXEC_SN, JOB_ID, JOB_EXEC_ID, EXEC_CLS_CD, EXEC_STAT_CD, EXEC_ST_DTTM, EXEC_END_DTTM, PROC_CNT, SUCC_CNT, FAIL_CNT, ERR_MSG_CONT, EXEC_SRV_NM, FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT ) VALUES ( #{dsptExecSn}, #{jobId}, #{jobExecId}, #{execClsCd}, #{execStatCd}, #{execStDttm}, #{execEndDttm}, #{procCnt}, #{succCnt}, #{failCnt}, #{errMsgCont}, #{execSrvNm}, #{firsRegrId}, CURRENT_TIMESTAMP, #{firsRegrId}, CURRENT_TIMESTAMP )

mapper.delete:
/* BatchExecutionMapper.deleteBatchExecutionByJobId 배치직무 ID에 해당하는 실행 이력을 모두 삭제한다. */
DELETE FROM TB_DSPT_EXEC_L
 WHERE JOB_ID = #{jobId}
